class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        unordered_map<int, int> left, right, count;
        int degree = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int x = nums[i];
            if (left.find(x) == left.end()) left[x] = i;
            right[x] = i;
            count[x]++;
            if (count[x] > degree) degree = count[x];
        }
        int ans = nums.size();
        for (auto& pair : count) {
            if (pair.second == degree) {
                int span = right[pair.first] - left[pair.first] + 1;
                if (span < ans) ans = span;
            }
        }
        return ans;
    }
};

class Solution {
    public int findShortestSubArray(int[] nums) {
        Map<Integer, Integer> left = new HashMap<>();
        Map<Integer, Integer> right = new HashMap<>();
        Map<Integer, Integer> count = new HashMap<>();
        int degree = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (!left.containsKey(x)) left.put(x, i);
            right.put(x, i);
            int c = count.getOrDefault(x, 0) + 1;
            count.put(x, c);
            if (c > degree) degree = c;
        }
        int ans = nums.length;
        for (int x : count.keySet()) {
            if (count.get(x) == degree) {
                int span = right.get(x) - left.get(x) + 1;
                if (span < ans) ans = span;
            }
        }
        return ans;
    }
}

var findShortestSubArray = function(nums) {
    const left = new Map();
    const right = new Map();
    const count = new Map();
    let degree = 0;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        if (!left.has(x)) left.set(x, i);
        right.set(x, i);
        const c = (count.get(x) || 0) + 1;
        count.set(x, c);
        if (c > degree) degree = c;
    }
    let ans = nums.length;
    for (const [x, c] of count.entries()) {
        if (c === degree) {
            const span = right.get(x) - left.get(x) + 1;
            if (span < ans) ans = span;
        }
    }
    return ans;
};
